+package com.example;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final MessageStore messageStore;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<Message> messages = new Grid<>(Message.class, false);
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        H1 heading = new H1("Contact");
+        RouterLink about = new RouterLink("About", AboutView.class);
+        FormLayout form = new FormLayout(name, email, phone, message, send);
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(event -> submit());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(event -> enableSending());
+        email.addValueChangeListener(event -> enableSending());
+        phone.addValueChangeListener(event -> enableSending());
+        message.addValueChangeListener(event -> enableSending());
+
+        messages.addColumn(Message::name).setHeader("Name");
+        messages.addColumn(Message::message).setHeader("Message");
+        messages.setItems(messageStore.getMessages());
+
+        add(heading, about, form, messages);
+    }
+
+    private void enableSending() {
+        send.setEnabled(true);
+    }
+
+    private void submit() {
+        clearValidation();
+
+        boolean valid = true;
+        if (isBlank(name.getValue())) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            valid = false;
+        }
+
+        String emailValue = value(email.getValue());
+        String phoneValue = value(phone.getValue());
+        boolean emailGiven = !isBlank(emailValue);
+        boolean phoneGiven = !isBlank(phoneValue);
+        if (emailGiven && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+            valid = false;
+        } else if (!emailGiven && !phoneGiven) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            valid = false;
+        }
+
+        String messageValue = value(message.getValue());
+        if (isBlank(messageValue)) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            valid = false;
+        } else if (messageValue.length() > 500) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            message.setInvalid(true);
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new Message(name.getValue(), emailValue, phoneValue, messageValue));
+        messages.setItems(messageStore.getMessages());
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        name.setErrorMessage("");
+        email.setInvalid(false);
+        email.setErrorMessage("");
+        message.setInvalid(false);
+        message.setErrorMessage("");
+    }
+
+    private static String value(String value) {
+        return value == null ? "" : value;
+    }
+
+    private static boolean isBlank(String value) {
+        return value(value).isBlank();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasDraft()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog confirmation = new Dialog();
+        confirmation.setCloseOnEsc(false);
+        confirmation.setCloseOnOutsideClick(false);
+        confirmation.add(new Span("You have an unfinished message. Leave without sending it?"));
+
+        Button keepEditing = new Button("Keep editing", click -> confirmation.close());
+        Button discard = new Button("Discard", click -> {
+            confirmation.close();
+            navigation.proceed();
+        });
+        confirmation.add(new HorizontalLayout(keepEditing, discard));
+        confirmation.open();
+    }
+
+    private boolean hasDraft() {
+        return !isBlank(name.getValue()) || !isBlank(email.getValue())
+                || !isBlank(phone.getValue()) || !isBlank(message.getValue());
+    }
+}
